import{c as r,Q as a,j as s,m as o}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"MemoHarness: Agent Harnesses That Learn from Experience","description":"","frontmatter":{"url":"https://arxiv.org/abs/2607.14159","title":"MemoHarness: Agent Harnesses That Learn from Experience","archived_date":"2026-07-20T00:00:00.000Z","arxiv_id":2607.14159,"pdf_path":"pdfs/2607.14159.pdf","source_routine":"routine-c","topic":"memoharness-six-control-surfaces-modular-decomposition"},"headers":[],"relativePath":"research/papers/2026-07-20-memoharness-six-control-surfaces-2607-14159.md","filePath":"research/papers/2026-07-20-memoharness-six-control-surfaces-2607-14159.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-07-20-memoharness-six-control-surfaces-2607-14159.md"};function n(l,e,i,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="memoharness-agent-harnesses-that-learn-from-experience" tabindex="-1">MemoHarness: Agent Harnesses That Learn from Experience <a class="header-anchor" href="#memoharness-agent-harnesses-that-learn-from-experience" aria-label="Permalink to &quot;MemoHarness: Agent Harnesses That Learn from Experience&quot;">​</a></h1><p><strong>Source</strong>: <a href="https://arxiv.org/abs/2607.14159" target="_blank" rel="noreferrer">https://arxiv.org/abs/2607.14159</a><strong>arXiv ID</strong>: 2607.14159 <strong>PDF</strong>: <a href="https://arxiv.org/abs/2607.14159" target="_blank" rel="noreferrer">research/papers/pdfs/2607.14159.pdf</a>（原始 push 因 relay 一次性 413 延遲，已於同日補推，見 git 歷史 <code>e17b029</code>）</p><hr><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>MemoHarness 是一個讓 agent harness 從自身執行歷史中學習的自適應框架，取代靜態固定配置。核心設計把 harness 沿推論的時間流拆解成六個可獨立編輯的控制介面（control surfaces）：</p><ol><li><strong>Context assembly</strong>（context — call 前輸入組裝）</li><li><strong>Tool interaction</strong>（tool — 外部工具與檢索使用）</li><li><strong>Generation control</strong>（generation — decoding 設定）</li><li><strong>Orchestration</strong>（orchestration — 工作流拓撲）</li><li><strong>Memory management</strong>（memory — 跨呼叫狀態持久化）</li><li><strong>Output processing</strong>（output — call 後輸出處理）</li></ol><p>將 harness search 從對單一不透明 prompt 的搜尋，轉為對六個可分離維度的結構化編輯。訓練期在此六維空間做 search，把逐案例診斷與蒸餾後的全域模式存入雙層 experience bank（case-level + distilled global pattern）；測試時不需 label/回饋/額外搜尋，僅靠檢索相似案例與相關模式，把選定的全域 harness 適配到每個未見測試案例。</p><p><strong>量化結果</strong>（Terminal-Bench shell-agent 主要基準）：MemoHarness 達 0.806，較最強基準 Codex 的 0.722 提升 +0.084（約 11.6% 相對提升）；同時成本從 Codex 基準 $10.28 降至 $6.89（約 33% 降低，即使因檢索 experience bank 而使用更多原始 input token，多數已被快取）。learned harness 對部分未見評測套件展現選擇性遷移能力（無需重新訓練）。</p><h2 id="對本-workspace-的影響" tabindex="-1">對本 workspace 的影響 <a class="header-anchor" href="#對本-workspace-的影響" aria-label="Permalink to &quot;對本 workspace 的影響&quot;">​</a></h2><ul><li>六控制介面拆解與 core.md 公理「判斷 vs 決定」呼應：本論文把 harness 優化本身也拆成「LLM 提案 patch」+「確定性測量認證」的模式（雙層 experience bank 的認證機制），與 2607.13683（07-15 已歸檔的 Self-Evolving Agent Harnesses）方法論高度相近，可交叉引用。</li><li>六維分類法（context/tool/generation/orchestration/memory/output）可作為本 workspace <code>.claude/rules/</code> 拆分現狀的一個外部參照框架——例如 core.md 目前混合了 orchestration（委派拓撲）與 output（展示紀律）等維度，未來若要進一步模組化可參考此分類。</li><li>成本降低（33%）同時提升成功率的組合，對 <code>finops</code>（v5.1 前已刪，無後繼 skill） skill 或 <code>core.md §PROPOSE 委派</code>（原 delegation-protocol.md）的「委派效益」計算提供一個可引用的外部基準數字。</li></ul>',10)])])}const g=r(t,[["render",n]]);export{d as __pageData,g as default};
